-- Reviewed recipe catalogue (seed owner only): corrected quantities and units,
-- clean ingredient names (one product per line, details in notes), French text,
-- recovered images and the no-pork/no-alcohol wording. Mirrors supabase/seeds/*.
--
-- Every change is guarded by the value the seed originally wrote: a field or an
-- ingredient list edited in the app since then is left as is and listed in the
-- notices. Ingredient lists are replaced as a whole (recipe ids are preserved);
-- product links are carried over by ingredient name. Safe to run twice.
-- Requires 20261031100000_v10_pantry_matching.sql (public.stock_name_tokens).
BEGIN;

-- Rows are [order_index, ingredient_name, quantity, unit, is_essential, notes].
-- Quantities compare at two decimals: the seeds were loaded into DECIMAL(10,2).
CREATE FUNCTION pg_temp.review_rows(p_rows jsonb)
RETURNS TABLE (o integer, n text, q numeric, u text, e boolean, t text) LANGUAGE sql IMMUTABLE AS $$
  SELECT (r->>0)::integer, r->>1, (r->>2)::numeric, r->>3, (r->>4)::boolean, r->>5 FROM jsonb_array_elements(p_rows) r
$$;
CREATE FUNCTION pg_temp.review_same(p_recipe uuid, p_rows jsonb) RETURNS boolean LANGUAGE sql STABLE AS $$
  WITH want AS (SELECT o, n, round(q, 2), u, e, t FROM pg_temp.review_rows(p_rows)),
       cur AS (SELECT order_index, ingredient_name, round(quantity, 2), unit, is_essential, coalesce(notes, '')
               FROM public.recipe_ingredients WHERE recipe_id = p_recipe)
  SELECT NOT EXISTS ((SELECT * FROM want EXCEPT ALL SELECT * FROM cur) UNION ALL (SELECT * FROM cur EXCEPT ALL SELECT * FROM want))
$$;
-- Replaces the list, keeping product links of ingredients whose name is unchanged.
CREATE FUNCTION pg_temp.review_replace(p_recipe uuid, p_rows jsonb) RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_links jsonb;
BEGIN
  SELECT coalesce(jsonb_object_agg(array_to_string(public.stock_name_tokens(ingredient_name), ' '), inventory_product_id)
           FILTER (WHERE inventory_product_id IS NOT NULL), '{}') INTO v_links
    FROM public.recipe_ingredients WHERE recipe_id = p_recipe;
  DELETE FROM public.recipe_ingredients WHERE recipe_id = p_recipe;
  INSERT INTO public.recipe_ingredients (recipe_id, order_index, ingredient_name, quantity, unit, is_essential, notes, inventory_product_id)
  SELECT p_recipe, o, n, q, u, e, nullif(t, ''), (v_links ->> array_to_string(public.stock_name_tokens(n), ' '))::uuid
    FROM pg_temp.review_rows(p_rows);
END $$;

