    UPDATE public.recipes SET description = $t$Thokku tamoul revisité au paneer : une préparation de tomates épicée et concentrée, mijotée jusqu'à ce que l'huile remonte, à laquelle on ajoute du paneer doré. Semi-sec, parfait avec des dosas, des idlis, du riz ou des chapatis.$t$ WHERE id = v_id AND md5(description) = '7228398fbff09ac93557d2190b49e444';
