    UPDATE public.recipes SET description = $t$Version express du cheung fun cantonais : la pâte de riz traditionnelle est remplacée par des galettes de riz vietnamiennes trempées, garnies de crevettes marinées et de cébette, roulées puis cuites à la vapeur. Sauce soja-huître-sésame-bouillon. Prêt en 25 min contre 1 h pour la version classique.$t$ WHERE id = v_id AND md5(description) = 'bb5704375fea4709f1c4d3fdcc4c4666';
