    UPDATE public.recipes SET description = $t$Musubi au katsu (poulet pané croustillant) glacé d'un mélange de miel pimenté (hot honey) et de beurre : deux ingrédients, un maximum d'effet. Posé sur du riz pressé au furikake et enveloppé d'une feuille de nori, entre street food hawaïenne et izakaya japonais.$t$ WHERE id = v_id AND md5(description) = 'e64ffb600eac95fb4c664ea0ce16f092';
