    UPDATE public.recipes SET description = $t$Butter chicken digne d'un restaurant étoilé : garam masala maison torréfié (laurier, cannelle, cardamome, coriandre, cumin, poivre, girofle), marinade yaourt-ail-gingembre-huile de moutarde, sauce tomate très concentrée en noix de cajou grillées, finition crème-beurre-fenugrec. Servi avec un pilaf de riz basmati sella.$t$ WHERE id = v_id AND md5(description) = 'd445a300ac18e153041efbe3d3d1f1a4';
