    UPDATE public.recipes SET instructions = $t$["Mariner les bouchées de poulet avec le curcuma, la coriandre moulue, le garam masala, le piment du Cachemire, le poivre noir, le sel, la pâte gingembre-ail, le jus de citron, le blanc d'œuf, la farine (maïda) et la fécule de maïs. Laisser reposer 10 à 15 min.",
