    UPDATE public.recipes SET description = $t$Canard frit indonésien : d'abord mijoté avec du curcuma, du galanga, de la citronnelle et des feuilles de salam et de combava, puis frit jusqu'à ce que la peau soit très croustillante. Servi avec un riz parfumé à la fleur de gingembre torche (kecombrang) et aux piments.$t$ WHERE id = v_id AND md5(description) = '93c5b4ccf7f6f896f4c976a0515685e3';
    GET DIAGNOSTICS v_n = ROW_COUNT; v_fields := v_fields + v_n;
    IF v_n = 0 AND NOT EXISTS (SELECT 1 FROM public.recipes WHERE id = v_id AND md5(description) = 'e04b49b3d908cd8b57d4c3dd5a0cee46') THEN v_kept := v_kept || 'Bebek Goreng Renyah avec Nasi Kecombrang · description'::text; END IF;
    UPDATE public.recipes SET image_url = 'https://www.nowjakarta.co.id/wp-content/uploads/2024/10/bebek2-scaled.jpeg' WHERE id = v_id AND image_url = 'https://www.nowjakarta.co.id/wp-content/uploads/2024/11/The-Rice-Table-Recipe-4-Bebek-Goreng-Renyah-with-Nasi-Kecombrang.jpg';
    GET DIAGNOSTICS v_n = ROW_COUNT; v_fields := v_fields + v_n;
    IF v_n = 0 AND NOT EXISTS (SELECT 1 FROM public.recipes WHERE id = v_id AND image_url IS NOT DISTINCT FROM 'https://www.nowjakarta.co.id/wp-content/uploads/2024/10/bebek2-scaled.jpeg') THEN v_kept := v_kept || 'Bebek Goreng Renyah avec Nasi Kecombrang · image_url'::text; END IF;
    UPDATE public.recipes SET instructions = $t$["Mixer les échalotes, l'ail et le curcuma jusqu'à obtenir une pâte lisse.",
"Faire revenir la pâte dans un peu d'huile chaude jusqu'à ce qu'elle soit dorée et parfumée.",
"Frotter le canard, à l'intérieur comme à l'extérieur, avec le sel, le sucre, le poivre et une partie de la pâte d'épices.",
"Mettre le canard dans une cocotte avec le reste de la pâte, les feuilles de salam, la citronnelle écrasée, les feuilles de combava, le galanga et le gingembre.",
"Ajouter l'eau, porter à ébullition puis laisser mijoter environ 45 minutes à feu doux.",
"Retirer le canard et le sécher soigneusement avec du papier absorbant.",
"Le frire à 180°C pendant 10 à 15 minutes en le retournant régulièrement, jusqu'à ce qu'il soit très croustillant.",
"Pour le riz : mixer le kecombrang, les piments et les échalotes en pâte, puis la cuire dans l'huile jusqu'à ce qu'elle caramélise et que l'huile se sépare. Assaisonner de bouillon de poulet en poudre.",
"Incorporer la pâte cuite au riz cuit à la vapeur et servir avec le canard frit."]
$t$ WHERE id = v_id AND md5(instructions) = '5b870dafd20dfe6907549f4569bba479';
